(1985267, 273035, 20214, '<td valign="top">Good Job! It sometimes pays to have an imagination and knowing how to use it. I''m impressed.</td>', 'Good Job! It sometimes pays to have an imagination and knowing how to use it. I''m impressed.', '2005-12-29 01:24:59.000000', NULL, 1),
(1985279, 273142, 20214, '<td valign="top">WOW! What a great shot! (10) Well done!</td>', 'WOW! What a great shot! (10) Well done!', '2005-12-29 01:26:39.000000', NULL, 1),
(1985294, 272782, 20214, '<td valign="top">I really don''t like giving low scores but I feel I have to here! Where are the patterns? Do I need a microscope to see them? The photo isn''t even in focus.</td>', 'I really don''t like giving low scores but I feel I have to here! Where are the patterns? Do I need a microscope to see them? The photo isn''t even in focus.', '2005-12-29 01:29:52.000000', NULL, 1),
(1985298, 272972, 25892, '<td valign="top">I think it could benefit from a little more DOF, after all it is patterns and the added depth could give more continuity to this pattern.</td>', 'I think it could benefit from a little more DOF, after all it is patterns and the added depth could give more continuity to this pattern.', '2005-12-29 01:31:06.000000', NULL, 1),
(1985310, 273071, 20214, '<td valign="top">I really like this photo and would love to see it on a wall 32 x 48 mounted and framed. Good shot!</td>', 'I really like this photo and would love to see it on a wall 32 x 48 mounted and framed. Good shot!', '2005-12-29 01:33:48.000000', NULL, 1),
(1985313, 272244, 20214, '<td valign="top">Clever idea and well done.</td>', 'Clever idea and well done.', '2005-12-29 01:34:38.000000', NULL, 1),
(1985321, 272098, 20214, '<td valign="top">Nice shot although I''m not sure about the saturation. You find patterns in the most unlikely spots. One just needs a keen eye and good imagination to find them. Well done! (9)</td>', 'Nice shot although I''m not sure about the saturation. You find patterns in the most unlikely spots. One just needs a keen eye and good imagination to find them. Well done! (9)', '2005-12-29 01:36:45.000000', NULL, 1),
