(1985339, 272870, 20214, '<td valign="top">Nice DOF!</td>', 'Nice DOF!', '2005-12-29 01:42:47.000000', NULL, 1),
(1985347, 272830, 20214, '<td valign="top">What a cool shot! I wonder how it would look in B&amp;W. Nice job!</td>', 'What a cool shot! I wonder how it would look in B&W. Nice job!', '2005-12-29 01:44:48.000000', NULL, 1),
(1985354, 273214, 20214, '<td valign="top">This is a good shot, although I find the lighting to be very distracting. Maybe if you took it later in the day when the lighting wasn''t so harsh it would have been better. Maybe even in B&amp;W.</td>', 'This is a good shot, although I find the lighting to be very distracting. Maybe if you took it later in the day when the lighting wasn''t so harsh it would have been better. Maybe even in B&W.', '2005-12-29 01:49:09.000000', NULL, 1),
(1985359, 272986, 20214, '<td valign="top">Good job! IMHO, I would have liked to seen this a little darker by adjusting the curves. (8)</td>', 'Good job! IMHO, I would have liked to seen this a little darker by adjusting the curves. (8)', '2005-12-29 01:51:43.000000', NULL, 1),
(1985361, 272753, 20214, '<td valign="top">I like these patterns a lot! LOL</td>', 'I like these patterns a lot! LOL', '2005-12-29 01:52:16.000000', NULL, 1),
(1985373, 272126, 20214, '<td valign="top">Nicely done, although I don''t really care for the border, but that''s just my opinion. (8)</td>', 'Nicely done, although I don''t really care for the border, but that''s just my opinion. (8)', '2005-12-29 01:57:33.000000', NULL, 1),
(1985388, 272731, 21362, '<td valign="top">Neat effect, would''ve been good for DOF too.</td>', 'Neat effect, would''ve been good for DOF too.', '2005-12-29 02:05:13.000000', NULL, 1),
(1985390, 273140, 21362, '<td valign="top">Interesting symmetry. I like it.</td>', 'Interesting symmetry. I like it.', '2005-12-29 02:05:57.000000', NULL, 1),
(1985393, 273217, 21362, '<td valign="top">I''m not sure about the very centered composition, but otherwise I really like this. Gorgeous flower, nice exposure. The blue corners are kind of interesting, however that came about.</td>', 'I''m not sure about the very centered composition, but otherwise I really like this. Gorgeous flower, nice exposure. The blue corners are kind of interesting, however that came about.', '2005-12-29 02:07:05.000000', NULL, 1),
(1985396, 271490, 21362, '<td valign="top">My favorite so far, after getting about 75% through the entries.  One of those simple everyday kind of scenes that you don''t really think about until you see it like this.</td>', 'My favorite so far, after getting about 75% through the entries.  One of those simple everyday kind of scenes that you don''t really think about until you see it like this.', '2005-12-29 02:08:05.000000', NULL, 1),
(1985399, 272537, 21362, '<td valign="top">Gorgeous. <br/> <br/>That''s not very helpful, but I don''t really have any criticism to offer. I just like it.</td>', 'Gorgeous.  That''s not very helpful, but I don''t really have any criticism to offer. I just like it.', '2005-12-29 02:08:42.000000', NULL, 1),
