(1985426, 273208, 40019, '<td valign="top">The lighting, textures and DOF are outstanding on this picture - I''m just not sure it''s what the voting public will see as "pattern".  I like it though!</td>', 'The lighting, textures and DOF are outstanding on this picture - I''m just not sure it''s what the voting public will see as "pattern".  I like it though!', '2005-12-29 02:29:21.000000', NULL, 1),
(1985448, 272782, 32084, '<td valign="top">Conceptually interesting - however, focus should be achieved somewhere, contrast is too low and the image apperas flat, and I''m not sure where this fits into a Pattern challenge.</td>', 'Conceptually interesting - however, focus should be achieved somewhere, contrast is too low and the image apperas flat, and I''m not sure where this fits into a Pattern challenge.', '2005-12-29 02:58:32.000000', NULL, 1),
(1985450, 273035, 32084, '<td valign="top">Neat idea.  I think either rotating to match the horizontal or forcing way off the horizontal would be better than just this very slight tilt.  Great texture.</td>', 'Neat idea.  I think either rotating to match the horizontal or forcing way off the horizontal would be better than just this very slight tilt.  Great texture.', '2005-12-29 03:03:24.000000', NULL, 1),
(1985455, 273217, 32084, '<td valign="top">Great eye for a natural pattern.  The focus here is challenging.  I think more DOF would help and less of a centralized composition.</td>', 'Great eye for a natural pattern.  The focus here is challenging.  I think more DOF would help and less of a centralized composition.', '2005-12-29 03:12:29.000000', NULL, 1),
