(1985588, 272698, 2022, '<td valign="top">Nice take on the challenge with the unusual subject made interesting. The only criticizm that I have is that DOF is a bit problematic, hard to see anything that is actually in focus. I am not sure if this is done on purpose or not. Maybe it is just me. (8)</td>', 'Nice take on the challenge with the unusual subject made interesting. The only criticizm that I have is that DOF is a bit problematic, hard to see anything that is actually in focus. I am not sure if this is done on purpose or not. Maybe it is just me. (8)', '2005-12-29 05:26:14.000000', NULL, 1),
(1985589, 272474, 2022, '<td valign="top">Great abstract. 10 in my books.</td>', 'Great abstract. 10 in my books.', '2005-12-29 05:26:41.000000', NULL, 1),
(1985590, 272193, 2022, '<td valign="top">Hmm...the connection to the challenge is ? The goose ? The grass ? (3)</td>', 'Hmm...the connection to the challenge is ? The goose ? The grass ? (3)', '2005-12-29 05:27:36.000000', NULL, 1),
(1985591, 271933, 18207, '<td valign="top">Clever double usage of harmonic division (~0.618 : 1) -- once at placement of center of cactus and once again if you count the spiral arms (13 to the right and 21 to the left which gives ~0.619 : 1).</td>', 'Clever double usage of harmonic division (~0.618 : 1) -- once at placement of center of cactus and once again if you count the spiral arms (13 to the right and 21 to the left which gives ~0.619 : 1).', '2005-12-29 05:28:24.000000', NULL, 1),
(1985592, 272317, 2022, '<td valign="top">Even an old tire makes for an interesting object. Great job (9)</td>', 'Even an old tire makes for an interesting object. Great job (9)', '2005-12-29 05:29:42.000000', NULL, 1),
