(1986885, 273218, 41554, '<td valign="top">Not bad, a little more DOF might have enhanced the pattern effect.</td>', 'Not bad, a little more DOF might have enhanced the pattern effect.', '2005-12-29 18:37:28.000000', NULL, 1),
