(1990702, 272824, 35804, '<td valign="top">Very elegant lighting... I also like the nice warm toning you have chosen for this image...so nice.</td>', 'Very elegant lighting... I also like the nice warm toning you have chosen for this image...so nice.', '2005-12-31 14:22:41.000000', NULL, 1),
(1990706, 272742, 35804, '<td valign="top">Love the tones and textures..very nice.</td>', 'Love the tones and textures..very nice.', '2005-12-31 14:24:21.000000', NULL, 1),
(1990726, 273003, 50369, '<td valign="top">This is gorgeous, I have shot similar photos with the same concept in mind, this is definitely a step further then I have ever taken it though.  Kudos.</td>', 'This is gorgeous, I have shot similar photos with the same concept in mind, this is definitely a step further then I have ever taken it though.  Kudos.', '2005-12-31 14:42:36.000000', NULL, 1),
(1990823, 273071, 17492, '<td valign="top">Woah! First 10 of the challenge, nicely done!</td>', 'Woah! First 10 of the challenge, nicely done!', '2005-12-31 15:56:51.000000', NULL, 1),
(1990843, 273141, 5746, '<td valign="top">IMHo the pattern would drive more attention if you cropp it to leave the leaves out. I like the shading. It''s so 3D to me. 8.</td>', 'IMHo the pattern would drive more attention if you cropp it to leave the leaves out. I like the shading. It''s so 3D to me. 8.', '2005-12-31 16:25:04.000000', NULL, 1),
(1990845, 273054, 5746, '<td valign="top">Looks like a skyscraper. Shadow on the right disturbs me a bit. Interesting angle.</td>', 'Looks like a skyscraper. Shadow on the right disturbs me a bit. Interesting angle.', '2005-12-31 16:26:10.000000', NULL, 1),
(1990847, 272788, 5746, '<td valign="top">There is a stone in the upper left corner? It disturbs the harmony. Looks grainy, but the effect is interesting. 7.</td>', 'There is a stone in the upper left corner? It disturbs the harmony. Looks grainy, but the effect is interesting. 7.', '2005-12-31 16:27:39.000000', NULL, 1),
(1990850, 273215, 5746, '<td valign="top">What an idea :) It''s like an optical ilussion.</td>', 'What an idea :) It''s like an optical ilussion.', '2005-12-31 16:29:37.000000', NULL, 1),
