(1990864, 272887, 5746, '<td valign="top">Probably one of the winners. Perfectly matches the challenge topic. The glass makes the pattern even stronger. 9.</td>', 'Probably one of the winners. Perfectly matches the challenge topic. The glass makes the pattern even stronger. 9.', '2005-12-31 16:56:13.000000', NULL, 1),
(1990866, 272194, 5746, '<td valign="top">Whatever it is - that''s what I expected from this challenge. 9.</td>', 'Whatever it is - that''s what I expected from this challenge. 9.', '2005-12-31 16:56:40.000000', NULL, 1),
(1990867, 273137, 5746, '<td valign="top">Was it made in zero gravity?<br/>Just joking :) Congratulations. 9 to me.</td>', 'Was it made in zero gravity?Just joking :) Congratulations. 9 to me.', '2005-12-31 16:57:20.000000', NULL, 1),
(1990868, 272867, 5746, '<td valign="top">That''s what I mean by "pattern" 8.</td>', 'That''s what I mean by "pattern" 8.', '2005-12-31 16:58:32.000000', NULL, 1),
(1990870, 273214, 5746, '<td valign="top">Great eye. I wish you focused on a smaller sqares. They are giving more interesting patern. 8.</td>', 'Great eye. I wish you focused on a smaller sqares. They are giving more interesting patern. 8.', '2005-12-31 16:59:29.000000', NULL, 1),
(1990871, 272892, 5746, '<td valign="top">Very minimalistic pattern. Nice shadow-play. 8.</td>', 'Very minimalistic pattern. Nice shadow-play. 8.', '2005-12-31 17:00:57.000000', NULL, 1),
(1990878, 272059, 36043, '<td valign="top">Great idea.  I think the lighting choice was not best - such strong side light does not really add to the message.</td>', 'Great idea.  I think the lighting choice was not best - such strong side light does not really add to the message.', '2005-12-31 17:08:58.000000', NULL, 1),
(1990879, 272993, 38234, '<td valign="top">I really liked this idea but the image is very soft in areas and I think a little more room on the outside would have helped the composition - as is, they are touching the frame in areas and appear squished.</td>', 'I really liked this idea but the image is very soft in areas and I think a little more room on the outside would have helped the composition - as is, they are touching the frame in areas and appear squished.', '2005-12-31 17:09:46.000000', NULL, 1),
(1990883, 272436, 38234, '<td valign="top">Nice iron piece but there appears to be a severe case of the jaggies on the edges.</td>', 'Nice iron piece but there appears to be a severe case of the jaggies on the edges.', '2005-12-31 17:12:03.000000', NULL, 1),
(1990884, 272784, 36043, '<td valign="top">Not sure the pattern of numbers nor letters is universal.  But good approach, nicely lit.</td>', 'Not sure the pattern of numbers nor letters is universal.  But good approach, nicely lit.', '2005-12-31 17:12:08.000000', NULL, 1),
(1990889, 273104, 38234, '<td valign="top">to me a head on shot would have worked better here as well as a wider DOF</td>', 'to me a head on shot would have worked better here as well as a wider DOF', '2005-12-31 17:14:43.000000', NULL, 1),
(1990890, 273250, 36043, '<td valign="top">A break in the pattern would have generated more interest - perhaps a blue or brown one replacing one on the thirds that is in moderate focus.  Good pattern none-the-less.  Perhaps also a bit more DOF (double it)?</td>', 'A break in the pattern would have generated more interest - perhaps a blue or brown one replacing one on the thirds that is in moderate focus.  Good pattern none-the-less.  Perhaps also a bit more DOF (double it)?', '2005-12-31 17:15:02.000000', NULL, 1),
(1990892, 272886, 36043, '<td valign="top">Too much DOF - need to blur the background on this or compose by angling more? Just MHO.  Nice subject matter.</td>', 'Too much DOF - need to blur the background on this or compose by angling more? Just MHO.  Nice subject matter.', '2005-12-31 17:16:38.000000', NULL, 1),
(1990894, 271792, 36043, '<td valign="top">First Leaf pattern that I''ve liked.  Well composed, good DOF, good strong contrast between light-dark green.</td>', 'First Leaf pattern that I''ve liked.  Well composed, good DOF, good strong contrast between light-dark green.', '2005-12-31 17:17:54.000000', NULL, 1),
(1990896, 272747, 36043, '<td valign="top">too centered, perhaps?  Good choice of subject matter.</td>', 'too centered, perhaps?  Good choice of subject matter.', '2005-12-31 17:22:28.000000', NULL, 1),
(1990910, 273198, 36043, '<td valign="top">Wow.  Doesn''t really seem like you could administer stiff punishment in this environment.</td>', 'Wow.  Doesn''t really seem like you could administer stiff punishment in this environment.', '2005-12-31 17:31:01.000000', NULL, 1),
(1990913, 272887, 36043, '<td valign="top">It doen''t look much like wine - is it really?</td>', 'It doen''t look much like wine - is it really?', '2005-12-31 17:32:49.000000', NULL, 1),
