(1998126, 272824, 8891, '<td valign="top">Great pattern and very nice tones.</td>', 'Great pattern and very nice tones.', '2006-01-03 10:54:22.000000', NULL, 1),
(1998127, 273035, 46634, '<td valign="top">Basic, simple, crisp,I like it</td>', 'Basic, simple, crisp,I like it', '2006-01-03 10:54:24.000000', NULL, 1),
