(2000362, 271490, 8891, '<td valign="top">This reminds me of the Marathon Grill at 19th and Market in Philly. The have the chairs set up on the wall there when not in use. The wall looks different here. Like the pattern...could have made a fine abstract by closing in on the stacks and shooting at an angle...but that''s probably just me. Nice find.</td>', 'This reminds me of the Marathon Grill at 19th and Market in Philly. The have the chairs set up on the wall there when not in use. The wall looks different here. Like the pattern...could have made a fine abstract by closing in on the stacks and shooting at an angle...but that''s probably just me. Nice find.', '2006-01-03 22:45:51.000000', NULL, 1),
(2000364, 272233, 8891, '<td valign="top">Great textures and tones...almost did this myself.</td>', 'Great textures and tones...almost did this myself.', '2006-01-03 22:46:24.000000', NULL, 1),
(2000365, 272975, 15574, '<td valign="top">Wow great focus, it''s kind of like an illusion.</td>', 'Wow great focus, it''s kind of like an illusion.', '2006-01-03 22:46:31.000000', NULL, 1),
(2000369, 272244, 8891, '<td valign="top">Ahhhh the cheese grater strikes again...Nice cnoice of the bright green in the background. Like the red and some blue reflections on next to the wholes. Fine abstract.  Good luck!</td>', 'Ahhhh the cheese grater strikes again...Nice cnoice of the bright green in the background. Like the red and some blue reflections on next to the wholes. Fine abstract.  Good luck!', '2006-01-03 22:48:00.000000', NULL, 1),
(2000378, 272996, 47487, '<td valign="top">WOW. I wish I''d taken this. (the best photographer''s compliment, right?) It just draws my eye right in.</td>', 'WOW. I wish I''d taken this. (the best photographer''s compliment, right?) It just draws my eye right in.', '2006-01-03 22:52:00.000000', NULL, 1),
(2000381, 271779, 47487, '<td valign="top">I like this. It''s a bit distracting, how the highlights almost look like faces on the bulbs, but the asymmetry and pattern are really visually pleasing. 8.</td>', 'I like this. It''s a bit distracting, how the highlights almost look like faces on the bulbs, but the asymmetry and pattern are really visually pleasing. 8.', '2006-01-03 22:52:55.000000', NULL, 1),
(2000384, 271933, 15574, '<td valign="top">Very Nice</td>', 'Very Nice', '2006-01-03 22:54:01.000000', NULL, 1),
