(2000401, 273137, 48717, '<td valign="top">I like this one a lot.  I would also like to see another version composed with just one perfect but large drop of water, like the one in the upper left corner.</td>', 'I like this one a lot.  I would also like to see another version composed with just one perfect but large drop of water, like the one in the upper left corner.', '2006-01-03 23:00:37.000000', NULL, 1),
(2000406, 273151, 48717, '<td valign="top">Beautiful color and lighting and pattern.  Nice capture.</td>', 'Beautiful color and lighting and pattern.  Nice capture.', '2006-01-03 23:02:32.000000', NULL, 1),
