(2000416, 272996, 48717, '<td valign="top">Great pattern, and I love contrast on this shot.  Perfectly exposed and processed.</td>', 'Great pattern, and I love contrast on this shot.  Perfectly exposed and processed.', '2006-01-03 23:06:13.000000', NULL, 1),
(2000418, 273153, 47487, '<td valign="top">I like this. Trying to decide if I''d like it better if it were more vertically symmetrical. I don''t think so. :) I like the blue. Good seeing; excellent capture.</td>', 'I like this. Trying to decide if I''d like it better if it were more vertically symmetrical. I don''t think so. :) I like the blue. Good seeing; excellent capture.', '2006-01-03 23:06:55.000000', NULL, 1),
