(2000434, 272209, 48717, '<td valign="top">Nice picture, but I don''t feel it truly fits the challenge.</td>', 'Nice picture, but I don''t feel it truly fits the challenge.', '2006-01-03 23:12:32.000000', NULL, 1),
(2000441, 273098, 48717, '<td valign="top">Sharper focus and higher contrast could have helped you out a lot here.  You have various shades of grey, but with more contrast your blacks would be black and your whites would be white.</td>', 'Sharper focus and higher contrast could have helped you out a lot here.  You have various shades of grey, but with more contrast your blacks would be black and your whites would be white.', '2006-01-03 23:14:06.000000', NULL, 1),
(2000447, 273190, 48717, '<td valign="top">Nicely composed, but your lighting needs a bit of work, there is a hot spot on the main leaf that could have been eliminated if the direct sunlight were eliminated.<br/><br/><i>Message edited by author 2006-01-04 01:10:21.</i></td>', 'Nicely composed, but your lighting needs a bit of work, there is a hot spot on the main leaf that could have been eliminated if the direct sunlight were eliminated.', '2006-01-03 23:16:07.000000', '2006-01-04 01:10:21.000000', 1),
(2000462, 272886, 48717, '<td valign="top">Love the color on this one, it just jumps off of my screen.  Nicely done.</td>', 'Love the color on this one, it just jumps off of my screen.  Nicely done.', '2006-01-03 23:21:05.000000', NULL, 1),
(2000463, 272251, 48717, '<td valign="top">Love this pattern, still trying to figure out what it is.  Nice lighting and focus.</td>', 'Love this pattern, still trying to figure out what it is.  Nice lighting and focus.', '2006-01-03 23:21:17.000000', NULL, 1),
