(2000477, 272652, 48717, '<td valign="top">I am bumping this way up, because althouhg the focus could be sharper, I love the color and composition on second view.</td>', 'I am bumping this way up, because althouhg the focus could be sharper, I love the color and composition on second view.', '2006-01-03 23:25:32.000000', NULL, 1),
