INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2000767, 273142, 23456, '<td valign="top">Great Lighting. This is fantastic, Well Done !</td>', 'Great Lighting. This is fantastic, Well Done !', '2006-01-04 00:36:12.000000', NULL, 0),
(2000779, 272886, 39184, '<td valign="top">Thanks for everybody''s comments.  It sounds almost completely unanimous!  You don''t like the people in the background...and now that I''ve been considering all the comments, I agree.  Day before yesterday I recropped and didn''t like the results, so I actually went back to reshoot the pic from a different angle and all of the bikes were scattered.  Oh well, I''ll try again from time to time.</td>', 'Thanks for everybody''s comments.  It sounds almost completely unanimous!  You don''t like the people in the background...and now that I''ve been considering all the comments, I agree.  Day before yesterday I recropped and didn''t like the results, so I actually went back to reshoot the pic from a different angle and all of the bikes were scattered.  Oh well, I''ll try again from time to time.', '2006-01-04 00:39:05.000000', NULL, 0),
(2000799, 272766, 48298, '<td valign="top">Thanks everyone!  Appreciate your kind comments!</td>', 'Thanks everyone!  Appreciate your kind comments!', '2006-01-04 00:42:26.000000', NULL, 0),
(2000814, 271810, 42826, '<td valign="top">Highly underrated....this shot was much better than a lot of the others...</td>', 'Highly underrated....this shot was much better than a lot of the others...', '2006-01-04 00:44:29.000000', NULL, 0),
