(2000907, 273071, 37961, '<td valign="top">Yay!! congrats and enjoy your Red. Great entry.</td>', 'Yay!! congrats and enjoy your Red. Great entry.', '2006-01-04 00:59:32.000000', NULL, 0),
(2000921, 273142, 37961, '<td valign="top">The Nautilus sea shell. Good job photographing this little work of art.</td>', 'The Nautilus sea shell. Good job photographing this little work of art.', '2006-01-04 01:00:43.000000', NULL, 0),
(2000968, 273142, 30861, '<td valign="top">Very nice job, congrats!</td>', 'Very nice job, congrats!', '2006-01-04 01:08:12.000000', NULL, 0),
